import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { PageTitle } from '../../../_metronic/layout/core';
import { KTIcon } from '../../../_metronic/helpers';
import axios from 'axios';

interface LocationState {
    selectedItems?: any[];
    item3PLMap?: { [key: string]: string };
}

const GenerateBordereaux: React.FC = () => {
    const location = useLocation();
    const navigate = useNavigate();

    // Type assertion for location.state
    const state = (location.state as LocationState) || {};
    const { selectedItems = [], item3PLMap = {} } = state;

    const [groupedBordereaux, setGroupedBordereaux] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [results, setResults] = useState<any[] | null>(null);

    useEffect(() => {
        if (!selectedItems || selectedItems.length === 0) {
            navigate('/orders-pending');
            return;
        }
        groupItems();
    }, [selectedItems]);

    const groupItems = () => {
        // Group by Seller + Order (one bordereau per seller per order)
        const groups: { [key: string]: any } = {};

        selectedItems.forEach((item: any) => {
            const sellerId = item.seller_id || item.vendor_id || 'unknown';
            const sellerName = item.seller_name || item.vendor || 'Unknown Seller';
            const orderId = item.order_id || item.entity_id;
            const incrementId = item.increment_id;

            // Use a composite key: seller_id + order_id
            const key = `${sellerId}_${orderId}`;

            if (!groups[key]) {
                groups[key] = {
                    key: key,
                    seller_id: sellerId,
                    seller_name: sellerName,
                    order_id: orderId,
                    increment_id: incrementId,
                    items: [],
                    carrier: item3PLMap?.[item.item_id] || 'Aramex',
                    shipping_cost: 7.00,
                    pieces: 1
                };
            }

            groups[key].items.push(item);
        });

        setGroupedBordereaux(Object.values(groups));
    };

    const handleInputChange = (key: string, field: string, value: any) => {
        setGroupedBordereaux(prev => prev.map(group =>
            group.key === key ? { ...group, [field]: value } : group
        ));
    };

    const handleSubmit = async () => {
        setLoading(true);
        try {
            const payload = {
                groups: groupedBordereaux.map(g => ({
                    seller_id: g.seller_id,
                    order_id: g.order_id,
                    items: g.items,
                    shipping_cost: parseFloat(g.shipping_cost),
                    pieces: parseInt(g.pieces),
                    carrier: g.carrier
                }))
            };

            const response = await axios.post('/api/bordereaux/generate', payload);

            if (response.data && response.data.results) {
                setResults(response.data.results);
            } else {
                alert("Erreur lors de la génération");
            }

        } catch (error: any) {
            console.error("Error generating bordereaux:", error);
            alert("Une erreur est survenue: " + (error.response?.data?.error || error.message));
        } finally {
            setLoading(false);
        }
    };

    if (results) {
        return (
            <>
                <PageTitle breadcrumbs={[]}>Génération terminée</PageTitle>
                <div className="card card-custom">
                    <div className="card-header border-0 pt-5">
                        <h3 className="card-title fw-bold">Résultats de la Génération</h3>
                    </div>
                    <div className="card-body">
                        <div className="row g-5">
                            {results.map((res, idx) => (
                                <div key={idx} className="col-md-6">
                                    <div className={`p-5 rounded border ${res.success ? 'bg-light-success border-success' : 'bg-light-danger border-danger'}`}>
                                        <h5 className="fw-bold">Commande #{res.order_id}</h5>
                                        {res.success ? (
                                            <div className="mt-2">
                                                <p className="text-success-emphasis">Succès! Tracking: <strong>{res.tracking_number}</strong></p>
                                                {res.label_url && (
                                                    <a href={res.label_url} target="_blank" rel="noopener noreferrer" className="btn btn-sm btn-primary mt-2">
                                                        <KTIcon iconName="cloud-download" className="fs-3" /> Télécharger l'étiquette
                                                    </a>
                                                )}
                                            </div>
                                        ) : (
                                            <p className="text-danger mt-2">Erreur: {res.error}</p>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="mt-10">
                            <button onClick={() => navigate('/orders-pending')} className="btn btn-secondary">
                                Retour aux commandes
                            </button>
                            <button onClick={() => navigate('/bordereau')} className="btn btn-primary ms-3">
                                Voir Historique
                            </button>
                        </div>
                    </div>
                </div>
            </>
        );
    }

    return (
        <>
            <PageTitle breadcrumbs={[]}>Générer Bordereaux</PageTitle>

            <div className='d-flex justify-content-center gap-4 mb-8'>
                <button
                    onClick={() => navigate('/orders-pending')}
                    className='btn btn-light-danger fw-bold'
                >
                    <KTIcon iconName='cross' className='fs-2' /> Annuler
                </button>

                <button
                    onClick={handleSubmit}
                    disabled={loading}
                    className='btn btn-success fw-bold'
                >
                    {loading ? (
                        <span className='spinner-border spinner-border-sm align-middle ms-2'></span>
                    ) : (
                        <><KTIcon iconName='double-check' className='fs-2' /> Valider et envoyer mail</>
                    )}
                </button>
            </div>

            <div className="row g-8">
                {groupedBordereaux.map((group, index) => (
                    <div key={group.key} className="col-12">
                        <div className="card shadow-sm">
                            <div className="card-header bg-dark py-4">
                                <h3 className="card-title text-white flex-column align-items-start">
                                    <span className="fw-bold fs-4">Bordereau N° {index + 1}</span>
                                    <span className="text-white opacity-75 fs-7">Commande #{group.increment_id} | Vendeur: {group.seller_name}</span>
                                </h3>
                                <div className="card-toolbar d-flex gap-5">
                                    <div className="d-flex align-items-center gap-2">
                                        <label className="text-white fs-7 fw-bold">Frais:</label>
                                        <div className="input-group input-group-sm w-125px">
                                            <input
                                                type="number"
                                                className="form-control"
                                                value={group.shipping_cost}
                                                onChange={(e) => handleInputChange(group.key, 'shipping_cost', e.target.value)}
                                            />
                                            <span className="input-group-text">TND</span>
                                        </div>
                                    </div>
                                    <div className="d-flex align-items-center gap-2">
                                        <label className="text-white fs-7 fw-bold">Pièces:</label>
                                        <input
                                            type="number"
                                            className="form-control form-control-sm w-80px"
                                            value={group.pieces}
                                            onChange={(e) => handleInputChange(group.key, 'pieces', e.target.value)}
                                        />
                                    </div>
                                    <div className="badge badge-light-primary fw-bold px-4 py-3 h-auto">
                                        Carrier: {group.carrier}
                                    </div>
                                </div>
                            </div>
                            <div className="card-body p-0">
                                <div className="table-responsive">
                                    <table className="table table-row-bordered table-row-gray-300 align-middle gs-9 gy-4">
                                        <thead className="bg-light">
                                            <tr className="fw-bold text-muted fs-7 text-uppercase">
                                                <th className="min-w-150px">Produit</th>
                                                <th className="text-center">Quantité</th>
                                                <th className="text-end">Prix Unitaire</th>
                                                <th className="text-end">Total</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {group.items.map((item: any, idx: number) => (
                                                <tr key={idx}>
                                                    <td>
                                                        <div className="text-dark fw-bold fs-6">{item.name}</div>
                                                        <div className="text-muted fs-7">SKU: {item.sku}</div>
                                                    </td>
                                                    <td className="text-center">
                                                        <span className="badge badge-light fw-bold">{item.qty_ordered}</span>
                                                    </td>
                                                    <td className="text-end fw-semibold">
                                                        {parseFloat(item.price).toFixed(2)} TND
                                                    </td>
                                                    <td className="text-end fw-bold text-primary">
                                                        {(parseFloat(item.price) * parseFloat(item.qty_ordered)).toFixed(2)} TND
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </>
    );
};

export default GenerateBordereaux;
